import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { Subscription } from 'rxjs';
import { Trip } from '../../models/trip';
import { TripService } from '../../services/trip.service';
import { AuthService } from '../../services/auth.service';
import { TripCardComponent } from '../trip-card/trip-card.component';

@Component({
  selector: 'app-trip-list',
  standalone: true,
  imports: [CommonModule, RouterModule, TripCardComponent],
  templateUrl: './trip-list.component.html',
  styleUrls: ['./trip-list.component.css']
})
export class TripListComponent implements OnInit, OnDestroy {
  trips: Trip[] = [];
  loading = true;
  error: string | null = null;
  isAuthenticated = false;
  private subscriptions: Subscription[] = [];

  constructor(
    private tripService: TripService,
    private authService: AuthService
  ) {}

  ngOnInit(): void {
    // Subscribe to authentication state
    this.subscriptions.push(
      this.authService.isAuthenticated$.subscribe(isAuth => {
        this.isAuthenticated = isAuth;
      })
    );

    this.loadTrips();
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach(sub => sub.unsubscribe());
  }

  loadTrips(): void {
    this.loading = true;
    this.error = null;

    this.subscriptions.push(
      this.tripService.getTrips().subscribe({
        next: (trips) => {
          this.trips = trips;
          this.loading = false;
        },
        error: (error) => {
          console.error('Error loading trips:', error);
          this.error = 'Failed to load trips. Please try again.';
          this.loading = false;
        }
      })
    );
  }

  onTripDeleted(tripId: string): void {
    // Remove the deleted trip from the local array
    this.trips = this.trips.filter(trip => trip._id !== tripId);
  }

  onTripUpdated(): void {
    // Reload trips to get the latest data
    this.loadTrips();
  }

  retryLoad(): void {
    this.loadTrips();
  }

  trackByTripId(index: number, trip: Trip): string {
    return trip._id || index.toString();
  }

  getAverageDuration(): string {
    if (this.trips.length === 0) return '0 days';

    const totalDays = this.trips.reduce((sum, trip) => {
      const days = parseInt(trip.length.match(/\d+/)?.[0] || '0');
      return sum + days;
    }, 0);

    const avgDays = Math.round(totalDays / this.trips.length);
    return `${avgDays} days`;
  }

  getPriceRange(): string {
    if (this.trips.length === 0) return '$0';

    const prices = this.trips.map(trip => {
      const priceStr = trip.perPerson.replace(/[$,]/g, '');
      return parseFloat(priceStr) || 0;
    });

    const minPrice = Math.min(...prices);
    const maxPrice = Math.max(...prices);

    if (minPrice === maxPrice) {
      return `$${minPrice.toLocaleString()}`;
    }

    return `$${minPrice.toLocaleString()} - $${maxPrice.toLocaleString()}`;
  }
}

<div class="container mt-4">
  <!-- Header Section -->
  <div class="row mb-4">
    <div class="col-12">
      <div class="d-flex justify-content-between align-items-center">
        <div>
          <h1 class="display-5 fw-bold text-primary">
            <i class="fas fa-map-marked-alt me-3"></i>Travel Packages
          </h1>
          <p class="lead text-muted">Discover amazing travel destinations and experiences</p>
        </div>
        <div *ngIf="isAuthenticated">
          <a routerLink="/add-trip" class="btn btn-success btn-lg">
            <i class="fas fa-plus me-2"></i>Add New Trip
          </a>
        </div>
      </div>
    </div>
  </div>

  <!-- Loading State -->
  <div *ngIf="loading" class="text-center py-5">
    <div class="spinner-border text-primary" role="status" style="width: 3rem; height: 3rem;">
      <span class="visually-hidden">Loading...</span>
    </div>
    <p class="mt-3 text-muted">Loading travel packages...</p>
  </div>

  <!-- Error State -->
  <div *ngIf="error && !loading" class="alert alert-danger" role="alert">
    <div class="d-flex align-items-center">
      <i class="fas fa-exclamation-triangle me-3"></i>
      <div class="flex-grow-1">
        <h5 class="alert-heading mb-1">Error Loading Trips</h5>
        <p class="mb-2">{{ error }}</p>
        <button class="btn btn-outline-danger btn-sm" (click)="retryLoad()">
          <i class="fas fa-redo me-1"></i>Try Again
        </button>
      </div>
    </div>
  </div>

  <!-- Empty State -->
  <div *ngIf="!loading && !error && trips.length === 0" class="text-center py-5">
    <div class="empty-state">
      <i class="fas fa-suitcase-rolling fa-4x text-muted mb-3"></i>
      <h3 class="text-muted">No Travel Packages Available</h3>
      <p class="text-muted">There are currently no travel packages to display.</p>
      <div *ngIf="isAuthenticated">
        <a routerLink="/add-trip" class="btn btn-primary">
          <i class="fas fa-plus me-2"></i>Add First Trip
        </a>
      </div>
    </div>
  </div>

  <!-- Trip Cards Grid -->
  <div *ngIf="!loading && !error && trips.length > 0" class="row">
    <div class="col-12 mb-3">
      <div class="d-flex justify-content-between align-items-center">
        <h5 class="text-muted mb-0">
          <i class="fas fa-list me-2"></i>{{ trips.length }} Travel Package{{ trips.length !== 1 ? 's' : '' }} Available
        </h5>
        <div class="btn-group" role="group">
          <input type="radio" class="btn-check" name="viewOptions" id="gridView" checked>
          <label class="btn btn-outline-secondary btn-sm" for="gridView">
            <i class="fas fa-th"></i>
          </label>
          <input type="radio" class="btn-check" name="viewOptions" id="listView">
          <label class="btn btn-outline-secondary btn-sm" for="listView">
            <i class="fas fa-list"></i>
          </label>
        </div>
      </div>
    </div>

    <!-- Trip Cards -->
    <div class="col-lg-4 col-md-6 col-sm-12 mb-4" *ngFor="let trip of trips; trackBy: trackByTripId">
      <app-trip-card 
        [trip]="trip" 
        [showAdminActions]="isAuthenticated"
        (tripDeleted)="onTripDeleted($event)"
        (tripUpdated)="onTripUpdated()">
      </app-trip-card>
    </div>
  </div>

  <!-- Statistics Section -->
  <div *ngIf="!loading && !error && trips.length > 0" class="row mt-5">
    <div class="col-12">
      <div class="card bg-light border-0">
        <div class="card-body">
          <div class="row text-center">
            <div class="col-md-3 col-6 mb-3">
              <div class="stat-item">
                <i class="fas fa-map-marked-alt fa-2x text-primary mb-2"></i>
                <h4 class="fw-bold">{{ trips.length }}</h4>
                <p class="text-muted mb-0">Destinations</p>
              </div>
            </div>
            <div class="col-md-3 col-6 mb-3">
              <div class="stat-item">
                <i class="fas fa-calendar-alt fa-2x text-success mb-2"></i>
                <h4 class="fw-bold">{{ getAverageDuration() }}</h4>
                <p class="text-muted mb-0">Avg Duration</p>
              </div>
            </div>
            <div class="col-md-3 col-6 mb-3">
              <div class="stat-item">
                <i class="fas fa-dollar-sign fa-2x text-warning mb-2"></i>
                <h4 class="fw-bold">{{ getPriceRange() }}</h4>
                <p class="text-muted mb-0">Price Range</p>
              </div>
            </div>
            <div class="col-md-3 col-6 mb-3">
              <div class="stat-item">
                <i class="fas fa-star fa-2x text-info mb-2"></i>
                <h4 class="fw-bold">4.8</h4>
                <p class="text-muted mb-0">Avg Rating</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>
